// Region consts generated by build.rs from memory_layout.toml, the single source for the flash layout
mod memory_layout {
    include!(concat!(env!("OUT_DIR"), "/memory_layout.rs"));
}
use memory_layout::*;
pub use memory_layout::{WIFI_CREDS_MAGIC, WIFI_CREDS_MAX_SSID_LEN, WIFI_CREDS_PSK_LEN};

pub const FW_ADDR: *const u8 = WIFI_FW_ORIGIN as *const u8;
pub const CLM_ADDR: *const u8 = WIFI_CLM_ORIGIN as *const u8;
pub const NVRAM_ADDR: *const u8 = WIFI_NVRAM_ORIGIN as *const u8;

// Sizes of the cyw43-firmware crate's actual blobs:
pub const FW_SIZE: usize = include_bytes!("../../../cyw43-firmware/43439A0.bin").len();
pub const CLM_SIZE: usize = include_bytes!("../../../cyw43-firmware/43439A0_clm.bin").len();
pub const NVRAM_SIZE: usize = include_bytes!("../../../cyw43-firmware/nvram_rp2040.bin").len();
const _: () = assert!(
    FW_SIZE <= WIFI_FW_LENGTH && CLM_SIZE <= WIFI_CLM_LENGTH && NVRAM_SIZE <= WIFI_NVRAM_LENGTH
);

// Per-device WiFi credentials, preflashed into the sector after the CYW43 blobs (outside ACTIVE/DFU)
pub const WIFI_CREDS_ADDR: *const u8 = WIFI_CREDS_ORIGIN as *const u8;
pub const WIFI_CREDS_SIZE: usize = WIFI_CREDS_LENGTH;

// Outside both binaries' RAM, so it survives the reset
pub const PANIC_LOG_ADDR: usize = PANIC_LOG_ORIGIN;
pub const PANIC_LOG_SIZE: usize = PANIC_LOG_LENGTH;
